                logging.info("Agent ran script with sudo privileges")
                return True
        except Exception as e:
            logging.error(f"Error reading solution file: {e}")

    if os.path.exists(script_log):
        try:
            with open(script_log, 'r') as f:
                content = f.read().lower()

            if 'sudo' in content:
                logging.info("Sudo execution found in log")
                return True
        except Exception as e:
            logging.error(f"Error reading script log: {e}")

    return False


